//! port::fmt (C printf / ostream number formatting) and port::nlohmann::dump against glibc and
//! nlohmann 3.8.0 output (fixtures/upstream-v1.18.2/unit/oracle/{printf_glibc,nlohmann_dump}.txt,
//! generated by oracle.cpp). PORTING.md §9 requires this table.

#[macro_use]
mod common;

use common::Cases;
use common::fixture;
use katago_core::core::global::Global;
use katago_core::port::fmt::PrintfArg;
use katago_core::port::fmt::cpp_ostream_f64;
use katago_core::port::fmt::cpp_ostream_f64_prec;
use katago_core::port::fmt::printf;
use katago_core::port::nlohmann;

fn f64_of_bits(hex: &str) -> f64 {
  f64::from_bits(u64::from_str_radix(hex, 16).unwrap())
}

wasm_test! {
fn printf_matches_glibc() {
  let mut cases = Cases::new("port_fmt::printf_matches_glibc");
  let table = fixture("oracle", "printf_glibc.txt");
  let mut failures: Vec<String> = Vec::new();
  for (lineno, line) in table.lines().enumerate() {
    let parts: Vec<&str> = line.splitn(4, '\t').collect();
    assert_eq!(parts.len(), 4, "bad table line {}: {:?}", lineno + 1, line);
    let (kind, fmt, arg, expected) = (parts[0], parts[1], parts[2], parts[3]);
    let actual: String = match kind {
      "i32" => printf(fmt, &[PrintfArg::I32(arg.parse().unwrap())]),
      "u32" => printf(fmt, &[PrintfArg::U32(arg.parse().unwrap())]),
      "i64" => printf(fmt, &[PrintfArg::I64(arg.parse().unwrap())]),
      "f64" => printf(fmt, &[PrintfArg::F64(f64_of_bits(arg))]),
      "str" => printf(fmt, &[PrintfArg::Str(arg)]),
      "char" => {
        if fmt == "%c%c" {
          printf(fmt, &[PrintfArg::Char(b'A'), PrintfArg::Char(b'z')])
        } else {
          printf(fmt, &[PrintfArg::Char(arg.as_bytes()[0])])
        }
      }
      "ostream" => {
        // fmt column holds the bits, arg = `out << x`, expected = `precision(17); out << x`
        let x = f64_of_bits(fmt);
        assert_eq!(cpp_ostream_f64(x), arg, "line {}: ostream << {:e}", lineno + 1, x);
        cpp_ostream_f64_prec(x, 17)
      }
      "ostreamf32" => {
        let x = f64_of_bits(fmt);
        assert_eq!(cpp_ostream_f64(x), arg, "line {}: ostream << (float){:e}", lineno + 1, x);
        Global::float_to_string(x as f32)
      }
      other => panic!("unknown kind {}", other),
    };
    if actual != expected {
      failures.push(format!("line {}: kind {} fmt {:?} arg {}: got {:?} want {:?}", lineno + 1, kind, fmt, arg, actual, expected));
    }
    cases.ran();
  }
  assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}
}

wasm_test! {
fn nlohmann_dump_matches_cpp() {
  let mut cases = Cases::new("port_fmt::nlohmann_dump_matches_cpp");
  let table = fixture("oracle", "nlohmann_dump.txt");
  for (lineno, line) in table.lines().enumerate() {
    let (a, expected) = line.split_once('\t').unwrap();
    if a == "OBJECT" {
      let mut obj = serde_json::Map::new();
      obj.insert("b".into(), serde_json::json!(1));
      obj.insert("a".into(), serde_json::json!("x\"y\\z\n\t\u{1}\u{1f} end \u{e9}"));
      obj.insert("c".into(), serde_json::json!([1, -2, 3.5, true, false, null, "s"]));
      obj.insert("d".into(), serde_json::json!({}));
      obj.insert("e".into(), serde_json::json!([]));
      obj.insert("f".into(), serde_json::json!(18446744073709551615u64));
      obj.insert("g".into(), serde_json::json!(i64::MIN));
      // NaN cannot be a serde_json number; nlohmann dumps NaN as null.
      obj.insert("h".into(), serde_json::Value::Null);
      obj.insert("Z".into(), serde_json::json!(0.5f32 as f64));
      assert_eq!(nlohmann::dump(&serde_json::Value::Object(obj)), expected, "line {}", lineno + 1);
    } else {
      let x = f64_of_bits(a);
      let actual = nlohmann::dump(&serde_json::json!(x));
      assert_eq!(actual, expected, "line {}: {:e} bits {}", lineno + 1, x, a);
    }
    cases.ran();
  }
}
}

wasm_test! {
/// Byte-level printf corners (review findings). Expected bytes are glibc 2.44 `snprintf` output
/// (scratch C program, x86-64): `%#.0o` of 0, `%c` as one raw byte, `%.Ns` cutting inside a UTF-8
/// character, `%s` stopping at NUL.
fn printf_byte_semantics_vs_glibc() {
  use katago_core::port::fmt::printf_bytes;
  let mut cases = Cases::new("printf_byte_semantics_vs_glibc");
  let s = |fmt: &str, args: &[PrintfArg]| printf(fmt, args);
  assert_eq!(s("%#.0o", &[PrintfArg::I32(0)]), "0");
  assert_eq!(s("%#5.0o|", &[PrintfArg::I32(0)]), "    0|");
  assert_eq!(s("%#-4.0o|", &[PrintfArg::I32(0)]), "0   |");
  assert_eq!(s("%.0o|", &[PrintfArg::I32(0)]), "|");
  assert_eq!(s("%#o|%#.3o|%#o", &[PrintfArg::I32(0), PrintfArg::I32(8), PrintfArg::I32(8)]), "0|010|010");
  cases.ran();
  assert_eq!(
    printf_bytes("%c|%3c|%-3c|", &[PrintfArg::Char(0xE9), PrintfArg::from('a'), PrintfArg::Char(0x80)]),
    b"\xe9|  a|\x80  |".to_vec()
  );
  assert_eq!(s("%c|", &[PrintfArg::I32(0x141)]), "A|");
  cases.ran();
  assert_eq!(
    printf_bytes("%.1s|%.2s|%5.1s|", &[PrintfArg::Str("\u{e9}"), PrintfArg::Str("\u{e9}x"), PrintfArg::Str("\u{e9}")]),
    b"\xc3|\xc3\xa9|    \xc3|".to_vec()
  );
  // The String wrapper cannot hold the lone byte: U+FFFD (TODO(port) in port::fmt::printf).
  assert_eq!(s("%.1s|", &[PrintfArg::Str("\u{e9}")]), "\u{fffd}|");
  cases.ran();
  assert_eq!(s("%s|%-5s|%3s|", &[PrintfArg::Str("ab\0cd"), PrintfArg::Str("a\0b"), PrintfArg::Str("\0zz")]), "ab|a    |   |");
  cases.ran();
}
}
